styles:
:root{--bg:#070807;--bg2:#0b0d0c;--panel:#101311;--paper:#f0eee8;--ink:#f4f2ec;--muted:#9b9d98;--line:rgba(255,255,255,.13);--red:#e81848;--green:#58b780;--green2:#9ed4b5;--greenDeep:#183526;--pad:clamp(20px,3.4vw,58px);--max:1480px;--ease:cubic-bezier(.16,1,.3,1);--font:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}img{display:block;width:100%}button{font:inherit}.shell{width:min(var(--max),100%);margin:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:#111;padding:10px 14px;transform:translateY(-150%)}.skip:focus{transform:none}.nav{height:82px;position:fixed;inset:0 0 auto;z-index:90;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,8,7,.76);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:18px;letter-spacing:-.04em}.brand img{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0}.nav-links a:hover,.nav-links a:focus-visible{color:white}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;position:relative}.menu-btn:before,.menu-btn span{content:"";position:absolute;left:13px;width:18px;height:1px;background:currentColor}.menu-btn:before{top:18px}.menu-btn span{top:26px}.mobile-menu{display:none;position:fixed;z-index:80;inset:82px 0 0;background:#070807;padding:32px var(--pad)}.mobile-menu.open{display:block}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}.mobile-menu a:last-child{color:var(--red)}
.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 19px;border:1px solid rgba(255,255,255,.24);font-size:13px;transition:.25s var(--ease)}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary{background:var(--red);border-color:var(--red)}.reveal{opacity:0;transform:translateY(22px);transition:opacity .72s var(--ease),transform .72s var(--ease)}.reveal.in{opacity:1;transform:none}
/* HERO */
.hero{min-height:100svh;padding-top:82px;position:relative;overflow:hidden;display:flex;align-items:flex-end;background:#070807}.hero-media{position:absolute;inset:82px 0 0}.hero-media img{height:100%;object-fit:cover;object-position:center;filter:saturate(.78) contrast(1.05) brightness(.62);transform:scale(1.025);will-change:transform}.hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,8,7,.05) 0%,rgba(7,8,7,.28) 42%,rgba(7,8,7,.92) 92%),linear-gradient(90deg,rgba(7,8,7,.9),rgba(7,8,7,.12) 66%)}.hero-shell{position:relative;z-index:2;width:min(var(--max),100%);margin:auto;padding:0 var(--pad) clamp(40px,5vw,72px)}.hero-meta{display:flex;justify-content:space-between;gap:20px;border-top:1px solid rgba(255,255,255,.24);padding-top:16px;margin-bottom:clamp(28px,4vw,56px)}.hero-meta span:last-child{color:#d1d1cc}.hero h1{font-size:clamp(60px,9.6vw,146px);line-height:.83;letter-spacing:-.075em;font-weight:500;margin:0;max-width:1300px}.hero h1 em{font-style:normal;color:var(--green2)}.hero-bottom{margin-top:clamp(28px,4vw,52px);display:grid;grid-template-columns:1fr .72fr;gap:42px;align-items:end}.hero-lede{font-size:clamp(18px,1.35vw,22px);max-width:760px;color:#dedbd4;letter-spacing:-.02em;margin:0}.hero-actions{justify-self:end;display:flex;gap:10px;align-items:center}.hero-mark{position:absolute;right:var(--pad);top:21%;z-index:2;width:clamp(108px,12vw,180px);aspect-ratio:1;border:1px solid rgba(255,255,255,.28);border-radius:50%;display:grid;place-items:center;text-align:center;font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:#eee}.hero-mark:before{content:"";position:absolute;inset:10px;border:1px solid rgba(88,183,128,.65);border-radius:50%}.hero-mark span{position:relative}
/* SNAPSHOT */
.snapshot{background:var(--paper);color:#10110f;padding:clamp(76px,8vw,128px) 0}.snapshot-head{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px;align-items:start}.snapshot h2{margin:0;font-size:clamp(44px,6.1vw,90px);line-height:.91;letter-spacing:-.063em;font-weight:500;max-width:1120px}.snapshot h2 em{font-style:normal;color:#2f8e5b}.snapshot-grid{margin-top:clamp(58px,7vw,96px);display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(0,0,0,.2)}.fact{padding:20px 24px 0 0;border-right:1px solid rgba(0,0,0,.16);min-height:148px}.fact:not(:first-child){padding-left:24px}.fact:last-child{border-right:0}.fact small{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#77726b;margin-bottom:18px}.fact strong{display:block;font-size:clamp(19px,1.7vw,27px);line-height:1.08;letter-spacing:-.035em;font-weight:520}.fact a{border-bottom:1px solid #111;padding-bottom:2px}
/* CHALLENGE */
.challenge{padding:clamp(90px,10vw,160px) 0;background:#080908}.challenge-grid{display:grid;grid-template-columns:.76fr 1.24fr;gap:clamp(58px,8vw,132px);align-items:start}.challenge-copy{position:sticky;top:120px}.challenge h2{font-size:clamp(50px,6.4vw,94px);line-height:.91;letter-spacing:-.065em;font-weight:500;margin:18px 0 28px}.challenge h2 span{color:var(--green2)}.challenge p{max-width:600px;color:#c8c6c0;font-size:clamp(17px,1.25vw,20px);margin:0}.challenge-visual{position:relative;min-height:760px}.challenge-visual .main{position:absolute;top:0;right:0;width:90%;height:68%;object-fit:cover;border-radius:4px;filter:saturate(.82)}.challenge-visual .detail{position:absolute;left:0;bottom:0;width:58%;height:43%;object-fit:cover;border:10px solid #080908;border-radius:4px;box-shadow:0 24px 90px rgba(0,0,0,.55)}.challenge-note{position:absolute;right:3%;bottom:7%;width:min(320px,40%);background:var(--green);color:#07110b;padding:23px;font-size:14px;line-height:1.38}.challenge-note b{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:16px}
/* INVENTORY STORY */
.inventory{height:420svh;position:relative;background:#0b0d0c}.inventory-sticky{position:sticky;top:82px;height:calc(100svh - 82px);display:grid;grid-template-columns:.86fr 1.14fr;overflow:hidden}.inventory-copy{padding:clamp(40px,5vw,72px) var(--pad);display:flex;flex-direction:column;border-right:1px solid rgba(255,255,255,.1);background:#0a0c0b}.inventory-top{display:flex;justify-content:space-between;gap:20px}.inventory-count{font-size:11px;letter-spacing:.16em;color:var(--green2)}.inventory-stage{position:relative;flex:1;display:flex;align-items:center}.inventory-step{position:absolute;inset:auto 0;opacity:0;visibility:hidden;transform:translateY(18px);transition:opacity .45s var(--ease),transform .55s var(--ease),visibility .45s}.inventory-step.active{opacity:1;visibility:visible;transform:none}.inventory-step .num{font-size:11px;letter-spacing:.16em;color:#777b77;margin-bottom:18px}.inventory-step h3{font-size:clamp(48px,5vw,78px);line-height:.91;letter-spacing:-.062em;font-weight:500;margin:0 0 24px}.inventory-step p{color:#c9c7c1;max-width:540px;font-size:clamp(16px,1.12vw,19px);margin:0}.inventory-tags{margin-top:28px;display:flex;flex-wrap:wrap;gap:8px}.inventory-tags span{border:1px solid rgba(255,255,255,.17);padding:8px 11px;font-size:11px;color:#d8d5cf}.inventory-progress{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.inventory-progress i{height:2px;background:rgba(255,255,255,.12);position:relative;overflow:hidden}.inventory-progress i:after{content:"";position:absolute;inset:0;background:var(--green);transform:scaleX(0);transform-origin:left;transition:transform .4s var(--ease)}.inventory[data-state="0"] .inventory-progress i:nth-child(1):after,.inventory[data-state="1"] .inventory-progress i:nth-child(-n+2):after,.inventory[data-state="2"] .inventory-progress i:nth-child(-n+3):after,.inventory[data-state="3"] .inventory-progress i:nth-child(-n+4):after{transform:scaleX(1)}
.inventory-visual{position:relative;background:#0f1210;padding:clamp(26px,3.2vw,46px);display:flex;align-items:center;justify-content:center;overflow:hidden}.browser{width:min(930px,94%);border:1px solid rgba(255,255,255,.16);background:#f6f6f2;color:#111;border-radius:5px;box-shadow:0 30px 120px rgba(0,0,0,.48);overflow:hidden;transform:translateY(0);transition:transform .65s var(--ease),box-shadow .65s var(--ease)}.browser-bar{height:38px;display:flex;align-items:center;gap:7px;padding:0 13px;background:#151816;color:#b9bdb8;font-size:10px}.browser-bar i{width:7px;height:7px;border-radius:50%;background:#555}.browser-bar span{margin-left:7px}.web-ui{min-height:560px;background:#f5f5f1;position:relative;overflow:hidden}.ui-head{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 4.6%;border-bottom:1px solid #ddd;background:#fff}.ui-logo{font-size:18px;font-weight:700;color:#2d8958}.ui-nav{display:flex;gap:18px;font-size:10px;color:#454945}.ui-hero{padding:48px 4.6% 34px;background:linear-gradient(120deg,#142219,#263b2d);color:#fff}.ui-hero small{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:#b6dac4}.ui-hero strong{display:block;margin-top:14px;font-size:clamp(28px,2.7vw,44px);line-height:.95;letter-spacing:-.05em;max-width:620px;overflow-wrap:anywhere;hyphens:auto}.ui-filter{margin:-12px 4.6% 0;background:#fff;border:1px solid #ddd;border-radius:4px;padding:18px;display:grid;grid-template-columns:repeat(4,1fr) auto;gap:8px;box-shadow:0 12px 30px rgba(0,0,0,.08)}.ui-filter span{border:1px solid #ddd;padding:10px;font-size:9px;color:#555;background:#fafafa}.ui-filter b{display:grid;place-items:center;background:#47a96e;color:#fff;padding:10px 16px;font-size:9px;font-weight:600}.ui-content{padding:28px 4.6%}.ui-title{font-size:12px;text-transform:uppercase;letter-spacing:.16em;color:#5c625d;margin-bottom:14px}.vehicle-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.vehicle{background:#fff;border:1px solid #ddd;min-height:150px;display:flex;flex-direction:column;justify-content:space-between}.vehicle-img{height:82px;background:linear-gradient(145deg,#282d29,#81857f);position:relative;overflow:hidden}.vehicle-img:after{content:"";position:absolute;width:66%;height:30%;border-radius:50% 50% 36% 36%;background:#d6d9d5;left:17%;bottom:17%;box-shadow:0 7px 0 #202420}.vehicle:nth-child(2) .vehicle-img{background:linear-gradient(145deg,#1b1d1c,#555a56)}.vehicle:nth-child(3) .vehicle-img{background:linear-gradient(145deg,#3c3f3d,#a8aaa7)}.vehicle:nth-child(4) .vehicle-img{background:linear-gradient(145deg,#1d2520,#68746d)}.vehicle span{padding:8px 9px 10px;font-size:9px;font-weight:650}.service-list{display:none;grid-template-columns:repeat(2,1fr);gap:10px}.service-box{border:1px solid #ddd;background:#fff;padding:18px;min-height:102px}.service-box small{font-size:9px;text-transform:uppercase;letter-spacing:.14em;color:#5b625d}.service-box strong{display:block;margin-top:12px;font-size:18px;letter-spacing:-.035em}.trust-panel{display:none;background:#fff;border:1px solid #ddd;padding:24px}.trust-panel strong{font-size:30px;line-height:1;letter-spacing:-.05em}.trust-panel p{max-width:560px;font-size:11px;color:#565b57}.trust-strip{margin-top:18px;display:flex;gap:7px;flex-wrap:wrap}.trust-strip span{border:1px solid #ddd;padding:7px 9px;font-size:9px}.inventory[data-state="1"] .ui-filter{box-shadow:0 0 0 2px rgba(88,183,128,.4),0 18px 45px rgba(0,0,0,.1)}.inventory[data-state="1"] .vehicle-grid{transform:translateY(-2px)}.inventory[data-state="2"] .vehicle-grid{display:none}.inventory[data-state="2"] .service-list{display:grid}.inventory[data-state="3"] .vehicle-grid,.inventory[data-state="3"] .service-list{display:none}.inventory[data-state="3"] .trust-panel{display:block}.inventory[data-state="3"] .ui-hero{background:linear-gradient(120deg,#0d1711,#1f4430)}.inventory[data-state="3"] .browser{transform:translateY(-4px);box-shadow:0 40px 140px rgba(0,0,0,.56)}.inventory-mobile-visual{display:none}
/* BRAND MOMENT */
.brand-moment{background:#dfe4df;color:#0a0b0a;padding:clamp(100px,10vw,160px) 0;overflow:hidden}.brand-ribbon{border-top:1px solid rgba(0,0,0,.22);border-bottom:1px solid rgba(0,0,0,.22);padding:18px var(--pad);margin-bottom:clamp(70px,8vw,118px)}.brand-ribbon div{width:min(var(--max),100%);margin:auto;font-size:clamp(34px,4.6vw,72px);line-height:.9;letter-spacing:-.06em;font-weight:500;display:flex;justify-content:space-between;gap:clamp(18px,2.2vw,34px);align-items:center}.brand-ribbon em{font-style:normal;color:#2c8054}.brand-grid{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px}.brand-grid h2{font-size:clamp(48px,6vw,88px);line-height:.92;letter-spacing:-.063em;font-weight:500;margin:0 0 26px;max-width:1000px}.brand-grid p{margin:0;max-width:690px;font-size:clamp(17px,1.2vw,20px);color:#333834}
/* FLOW */
.flow{background:#080908;padding:clamp(94px,10vw,160px) 0}.flow-head{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px;margin-bottom:clamp(55px,7vw,90px)}.flow h2{font-size:clamp(48px,6vw,88px);line-height:.92;letter-spacing:-.063em;font-weight:500;margin:0}.flow h2 em{font-style:normal;color:var(--green2)}.flow-list{border-top:1px solid var(--line)}.flow-row{display:grid;grid-template-columns:70px .7fr 1fr;gap:24px;padding:28px 0;border-bottom:1px solid var(--line);align-items:start}.flow-row .n{font-size:11px;letter-spacing:.14em;color:var(--green2)}.flow-row strong{font-size:clamp(25px,2.5vw,38px);line-height:1;letter-spacing:-.045em;font-weight:500}.flow-row p{margin:0;color:#aaa9a4;max-width:620px;overflow-wrap:anywhere;hyphens:auto}
/* LOCAL */
.local{background:#111411;padding:clamp(92px,10vw,156px) 0}.local-grid{display:grid;grid-template-columns:1fr .86fr;gap:clamp(60px,8vw,130px)}.local h2{font-size:clamp(54px,7.3vw,108px);line-height:.87;letter-spacing:-.07em;font-weight:500;margin:18px 0 28px}.local h2 span{color:var(--green2)}.local p{color:#c1c1bb;max-width:620px;font-size:clamp(17px,1.2vw,20px)}.places{align-self:end;border-top:1px solid var(--line)}.place{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid var(--line)}.place strong{font-size:clamp(20px,2vw,29px);font-weight:500}.place span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#8f938e}
/* LIVE / NEXT */
.live{background:var(--paper);color:#111;padding:clamp(90px,10vw,150px) 0}.live-head{display:grid;grid-template-columns:1fr .62fr;gap:50px;align-items:end;margin-bottom:42px}.live h2{font-size:clamp(56px,7.6vw,112px);line-height:.87;letter-spacing:-.07em;font-weight:500;margin:0}.live h2 span{color:#2d8758}.live p{margin:0 0 7px;font-size:clamp(17px,1.2vw,20px);color:#4d514d}.live-frame{display:block;position:relative;overflow:hidden;border-radius:4px}.live-frame img{aspect-ratio:16/8.8;object-fit:cover;transition:transform 1.1s var(--ease)}.live-frame:hover img{transform:scale(1.025)}.next{background:#070807;padding:clamp(88px,10vw,150px) 0}.next-grid{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px}.next h2{font-size:clamp(58px,8.4vw,128px);line-height:.85;letter-spacing:-.072em;font-weight:500;margin:0}.next h2 span{color:var(--red)}.next-row{display:flex;justify-content:space-between;gap:40px;align-items:flex-end;margin-top:42px;border-top:1px solid var(--line);padding-top:20px}.next-row p{max-width:480px;color:#aaa8a3;margin:0}.next-link{font-size:13px;border-bottom:1px solid rgba(255,255,255,.35);padding-bottom:3px}
.footer{background:#050605;border-top:1px solid var(--line);padding:60px 0 24px}.footer-top{display:grid;grid-template-columns:1fr 1.2fr;gap:60px}.footer-brand{font-size:clamp(54px,8vw,118px);line-height:.8;letter-spacing:-.075em;font-weight:700}.footer-top p{color:#8f918d;max-width:360px}.footer-map{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.footer-map strong{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;margin-bottom:15px;color:#858884}.footer-map a,.footer-map span{display:block;color:#c5c4bf;font-size:14px;padding:4px 0}.footer-bottom{margin-top:70px;border-top:1px solid var(--line);padding-top:18px;display:flex;justify-content:space-between;gap:20px;color:#777a76;font-size:11px}.footer-bottom div{display:flex;gap:18px}
@media(max-width:1050px){.nav-links{display:none}.menu-btn{display:block}.hero h1{font-size:clamp(66px,12.6vw,126px)}.snapshot-head,.brand-grid,.flow-head,.next-grid{grid-template-columns:1fr;gap:24px}.challenge-grid{grid-template-columns:1fr}.challenge-copy{position:relative;top:auto}.challenge-visual{min-height:690px;margin-top:20px}.inventory-sticky{grid-template-columns:.95fr 1.05fr}.inventory-step h3{font-size:clamp(42px,5.5vw,60px)}.web-ui{min-height:500px}.ui-filter{grid-template-columns:repeat(2,1fr);}.ui-filter b{grid-column:1/-1}.vehicle-grid{grid-template-columns:repeat(2,1fr)}.vehicle:nth-child(n+3){display:none}.local-grid{grid-template-columns:1fr;}.live-head{grid-template-columns:1fr;}.footer-top{grid-template-columns:1fr}.footer-map{max-width:720px}}
@media(max-width:820px){.nav{height:72px}.mobile-menu{inset:72px 0 0}.hero{padding-top:72px;min-height:900px}.hero-media{inset:72px 0 0}.hero-media img{object-position:63% center}.hero-shell{padding-bottom:38px}.hero-meta{margin-bottom:30px}.hero-meta span:last-child{display:none}.hero h1{font-size:clamp(55px,15.6vw,94px);max-width:8ch}.hero-bottom{grid-template-columns:1fr;gap:24px}.hero-actions{justify-self:start}.hero-mark{display:none}.snapshot-grid{grid-template-columns:1fr 1fr}.fact:nth-child(2){border-right:0}.fact:nth-child(n+3){border-top:1px solid rgba(0,0,0,.16);padding-top:20px}.challenge-visual{min-height:0;display:grid;grid-template-columns:1fr;gap:14px}.challenge-visual .main,.challenge-visual .detail{position:relative;inset:auto;width:100%;height:auto;aspect-ratio:16/10;object-fit:cover;border:0}.challenge-note{position:relative;inset:auto;width:100%;}.inventory{height:auto;padding:86px 0}.inventory-sticky{position:relative;top:auto;height:auto;display:block;overflow:visible}.inventory-copy{padding:0 var(--pad);border:0}.inventory-top{margin-bottom:42px}.inventory-stage{display:block}.inventory-step{position:relative;opacity:1;visibility:visible;transform:none;padding:0 0 76px;margin-bottom:76px;border-bottom:1px solid var(--line)}.inventory-step:last-child{margin-bottom:0}.inventory-step h3{font-size:clamp(44px,11vw,68px)}.inventory-progress,.inventory-visual{display:none}.inventory-mobile-visual{display:block;margin-top:28px}.mobile-ui{background:#f5f5f1;color:#111;border-radius:4px;overflow:hidden;border:1px solid rgba(255,255,255,.1)}.mobile-ui .browser-bar{height:34px}.mobile-ui .ui-head{height:54px;padding:0 16px}.mobile-ui .ui-nav{display:none}.mobile-ui .ui-hero{padding:32px 16px 24px}.mobile-ui .ui-hero strong{font-size:30px}.mobile-ui .ui-filter{margin:-8px 16px 0;padding:12px;grid-template-columns:1fr 1fr}.mobile-ui .ui-filter b{grid-column:1/-1}.mobile-ui .ui-content{padding:20px 16px}.mobile-ui .vehicle-grid{grid-template-columns:1fr 1fr}.mobile-ui .vehicle:nth-child(n+3){display:none}.mobile-ui .service-list{grid-template-columns:1fr}.brand-ribbon{padding-inline:var(--pad)}.brand-ribbon div{font-size:clamp(31px,8.8vw,48px);display:block;padding:0}.brand-ribbon div span,.brand-ribbon div em{display:block;margin-bottom:8px;white-space:normal;overflow-wrap:anywhere}.flow-row{grid-template-columns:40px 1fr;gap:12px}.flow-row p{grid-column:2}.local h2{font-size:clamp(58px,15vw,96px)}.next-row{display:grid}.footer-map{grid-template-columns:1fr 1fr}.footer-bottom{display:grid}}
@media(max-width:480px){.hero{min-height:820px}.hero h1{font-size:clamp(52px,16.3vw,75px)}.hero-actions{display:grid;width:100%}.hero-actions .btn{width:100%}.snapshot-grid{grid-template-columns:1fr}.fact,.fact:not(:first-child){border-right:0;padding-left:0}.fact:nth-child(n+2){border-top:1px solid rgba(0,0,0,.16);padding-top:20px}.challenge h2{font-size:clamp(48px,14vw,66px)}.brand-grid h2,.flow h2{font-size:clamp(46px,13vw,64px)}.footer-map{grid-template-columns:1fr}.footer-bottom div{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.reveal{opacity:1;transform:none;transition:none}.hero-media img,.live-frame img,.browser{transform:none!important;transition:none!important}}

/* REAL WEBSITE ASSET PASS */
.real-site-showcase{--case:#e81848;background:#0a0a0a;color:#f3efe9;padding:clamp(90px,10vw,160px) 0;border-top:1px solid rgba(255,255,255,.09);border-bottom:1px solid rgba(255,255,255,.09)}
.real-site-shell{width:min(1480px,100%);margin:0 auto;padding:0 clamp(20px,4vw,68px)}
.real-site-head{display:grid;grid-template-columns:minmax(0,1.18fr) minmax(280px,.62fr);gap:clamp(34px,7vw,100px);align-items:end;margin-bottom:clamp(42px,5vw,72px)}
.real-site-kicker{display:block;color:var(--case);font-size:10px;letter-spacing:.18em;text-transform:uppercase;margin-bottom:18px}
.real-site-head h2{font-size:clamp(48px,6.4vw,104px);line-height:.9;letter-spacing:-.065em;font-weight:520;margin:0;max-width:980px}
.real-site-head p{margin:0;color:#aaa59e;font-size:clamp(16px,1.15vw,19px);line-height:1.55;max-width:520px}
.real-site-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.real-site-card{display:block;color:inherit;text-decoration:none;min-width:0;background:#101010;border:1px solid rgba(255,255,255,.14);border-radius:6px;overflow:hidden;transition:transform .6s cubic-bezier(.16,1,.3,1),border-color .4s ease}
.real-site-card:hover{transform:translateY(-5px);border-color:color-mix(in srgb,var(--case) 60%,#fff 10%)}
.real-browser-bar{height:42px;background:#0c0c0c;border-bottom:1px solid rgba(255,255,255,.1);display:flex;align-items:center;gap:6px;padding:0 13px;overflow:hidden}
.real-browser-bar i{width:7px;height:7px;border-radius:50%;background:#383838;flex:0 0 auto}
.real-browser-bar span{margin-left:8px;color:#77736d;font-size:9px;letter-spacing:.08em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.real-shot{position:relative;aspect-ratio:16/10;overflow:hidden;background:#141414}
.real-shot img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top center;opacity:0;transform:scale(1.01);transition:opacity .45s ease,transform 1.1s cubic-bezier(.16,1,.3,1)}
.real-shot.loaded img{opacity:1}
.real-site-card:hover .real-shot.loaded img{transform:scale(1.035)}
.real-fallback{position:absolute;inset:0;padding:clamp(22px,3vw,42px);display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#111,#171717);z-index:0}
.real-fallback:before{content:"";position:absolute;left:0;top:0;width:4px;height:100%;background:var(--case);opacity:.85}
.real-fallback small{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#7c7872}
.real-fallback strong{font-size:clamp(32px,4.2vw,68px);line-height:.9;letter-spacing:-.055em;font-weight:520;max-width:620px;overflow-wrap:anywhere;hyphens:auto}
.real-fallback strong span{color:var(--case)}
.real-caption{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end;padding:20px 20px 22px;border-top:1px solid rgba(255,255,255,.08)}
.real-caption strong{display:block;font-size:20px;letter-spacing:-.025em;font-weight:500;margin-bottom:4px}
.real-caption span{display:block;color:#8c8881;font-size:12px;line-height:1.45}
.real-caption b{font-size:18px;color:var(--case);font-weight:400}
.real-site-card--hero{grid-column:1/-1}
.real-site-card--hero .real-shot{aspect-ratio:2.05/1}
.real-site-card--single{grid-column:1/-1}
.real-site-card--single .real-shot{aspect-ratio:2/1}
@media(max-width:900px){.real-site-head{grid-template-columns:1fr;gap:24px}.real-site-grid{grid-template-columns:1fr}.real-site-card--hero,.real-site-card--single{grid-column:auto}.real-site-card--hero .real-shot,.real-site-card--single .real-shot,.real-shot{aspect-ratio:16/10}}
@media(max-width:520px){.real-site-showcase{padding:78px 0}.real-site-shell{padding:0 14px}.real-site-head h2{font-size:12.5vw}.real-caption{padding:16px}.real-caption strong{font-size:18px}.real-fallback strong{font-size:clamp(30px,8.6vw,44px);line-height:.9}}
@media(prefers-reduced-motion:reduce){.real-site-card,.real-shot img{transition:none!important}.real-site-card:hover,.real-site-card:hover .real-shot.loaded img{transform:none!important}}


/* AROZ R3: Documented static editorial case artwork, not third-party website screenshots. */
.case-static-shot{background:radial-gradient(circle at 93% 8%,color-mix(in srgb,var(--case) 12%,transparent),transparent 47%),#111}
.case-static-shot .real-fallback{background:linear-gradient(140deg,#101012 0%,#1a181b 70%,#151215 100%);isolation:isolate}
.case-static-shot .real-fallback small{font-size:clamp(11px,1vw,13px)!important;color:#c9bebd;letter-spacing:.1em}
.case-static-shot .real-fallback strong{font-weight:520;letter-spacing:-.06em;max-width:85%}
.case-original-art .case-static-shot{background-image:linear-gradient(92deg,rgba(7,7,10,.94),rgba(7,7,10,.21)),url('assets/aroz-local-project-visual.webp');background-size:cover;background-position:center}
.case-original-art .case-static-shot .real-fallback{background:linear-gradient(90deg,rgba(5,5,8,.8) 0%,rgba(5,5,8,.25) 66%,rgba(5,5,8,.2));}
.case-original-art .case-static-shot .real-fallback strong{color:#fff;text-shadow:0 2px 9px rgba(0,0,0,.45)}
@media(max-width:520px){.case-static-shot .real-fallback{padding:22px!important}.case-static-shot .real-fallback strong{font-size:clamp(28px,7.2vw,44px)!important;max-width:95%;line-height:1.02}}
@media(prefers-reduced-motion:reduce){.real-site-card{transition:none!important}.real-site-card:hover{transform:none!important}}

/* AROZ R2 – detail craft / accessibility; scoped additions only. */
html { scroll-padding-top: 90px; }
:where(h1,h2,h3) { text-wrap: balance; }
:where(p,li,dd) { overflow-wrap: break-word; }
:where(a, button, input, select, textarea):focus-visible { outline: 2px solid #ff4164; outline-offset: 4px; box-shadow: 0 0 0 2px rgba(0,0,0,.5); }
:where(button, input, textarea, select) { font: inherit; }
:where(img) { max-width:100%; }
@media(prefers-reduced-motion:reduce){ html{scroll-behavior:auto!important} *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important} }
@media(max-width:620px){
 :where(h1,h2,h3) { hyphens:auto; overflow-wrap:normal; }
 :where(p) { line-height:1.55; }
 :where(a,button) { -webkit-tap-highlight-color:transparent; }
}

/* Typography AA craft floor for legacy 8-10px labels */
.hero-mark{font-size:12px!important}
.fact small{font-size:12px!important}
.challenge-note b{font-size:12px!important}
.browser-bar{font-size:12px!important}
.ui-nav{font-size:12px!important}
.ui-hero small{font-size:12px!important}
.ui-filter span{font-size:12px!important}
.ui-filter b{font-size:12px!important}
.vehicle span{font-size:12px!important}
.service-box small{font-size:12px!important}
.trust-strip span{font-size:12px!important}
.real-site-kicker{font-size:12px!important}
.real-browser-bar span{font-size:12px!important}
.real-fallback small{font-size:12px!important}


/* P1: primary case metadata legible; preserve page-specific color palette. */
@media(max-width:820px){
 :where(.hero h1){line-height:1.01;overflow-wrap:normal}
 :where(.hero-lede, .case-intro p, .challenge-copy p){line-height:1.55}
}
